import{_ as t,c as a,ae as o,o as r}from"./chunks/framework.Buicxtqr.js";const p=JSON.parse('{"title":"Get Models for BuddyGenAI","description":"","frontmatter":{},"headers":[],"relativePath":"getting-models.md","filePath":"getting-models.md"}'),d={name:"getting-models.md"};function l(i,e,n,s,h,c){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="get-models-for-buddygenai" tabindex="-1">Get Models for BuddyGenAI <a class="header-anchor" href="#get-models-for-buddygenai" aria-label="Permalink to &quot;Get Models for BuddyGenAI&quot;">​</a></h1><p><a href="https://github.com/parsehex/BuddyGenAI/blob/main/docs/getting-models.md" target="_blank" rel="noreferrer">View the current version of this page</a></p><p>BuddyGenAI uses AI models to chat, generate text, images, TTS and Speech-to-Text. TTS and Speech-to-Text are optional, but you&#39;re required to provide a chat and an image model.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to &quot;Compatibility&quot;">​</a></h2><p>You&#39;ll need to determine what models your GPU is able to run. The less VRAM your GPU has, the smaller the model you&#39;ll need to use. You might be able to run larger models on a GPU with less VRAM, but it will be slower and may crash.</p><p>First, check how much VRAM your GPU has. You can do this by opening Task Manager, going to the Performance tab, and clicking on GPU. You&#39;ll see a graph of your GPU usage and the amount of VRAM your GPU has. Note how much VRAM you have available.</p><p>The following sections provide estimates of the VRAM required for each model. The list of models is not exhaustive but are the models I&#39;ve used with the app (RTX 3060 12GB).</p><p>The app expects the following file extensions for models:</p><ul><li>Chat Model: <code>.gguf</code></li><li>Image Model: <code>.safetensors</code></li><li>TTS Voice: <code>.onnx</code> and adjacent <code>.json</code></li><li>Speech-to-Text Model: <code>.bin</code></li></ul><h2 id="chat-models-required" tabindex="-1">Chat Models (Required) <a class="header-anchor" href="#chat-models-required" aria-label="Permalink to &quot;Chat Models (Required)&quot;">​</a></h2><p>My preferred chat model has been Meta&#39;s Llama 3, <a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF" target="_blank" rel="noreferrer">quantized by bartowski</a>. You can find links to download quanized/smaller versions of the model below.</p><p>(The higher the number e.g. Q8, the better the model, but the more VRAM it will require.)</p><table tabindex="0"><thead><tr><th>Model</th><th>File Size</th><th>Est. VRAM Usage</th><th></th></tr></thead><tbody><tr><td>Q2_K</td><td>3.17GB</td><td>4.5GB</td><td><a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF/blob/main/Meta-Llama-3-8B-Instruct-Q2_K.gguf" target="_blank" rel="noreferrer">Download</a></td></tr><tr><td>Q4_K_M</td><td>4.92GB</td><td>5.9GB</td><td><a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF/blob/main/Meta-Llama-3-8B-Instruct-Q4_K_M.gguf" target="_blank" rel="noreferrer">Download</a></td></tr><tr><td>Q8_0</td><td>8.54GB</td><td>9.1GB</td><td><a href="https://huggingface.co/bartowski/Meta-Llama-3-8B-Instruct-GGUF/blob/main/Meta-Llama-3-8B-Instruct-Q8_0.gguf" target="_blank" rel="noreferrer">Download</a></td></tr></tbody></table><h2 id="image-model-required" tabindex="-1">Image Model (Required) <a class="header-anchor" href="#image-model-required" aria-label="Permalink to &quot;Image Model (Required)&quot;">​</a></h2><p>I&#39;ve been using <a href="https://civitai.com/models/36281?modelVersionId=244831" target="_blank" rel="noreferrer">Toonify SD 1.5</a>.</p><table tabindex="0"><thead><tr><th>Model</th><th>File Size</th><th>Est. VRAM Usage</th><th></th></tr></thead><tbody><tr><td>Toonify SD 1.5</td><td>1.98GB</td><td>3GB</td><td><a href="https://civitai.com/api/download/models/244831" target="_blank" rel="noreferrer">Download</a></td></tr></tbody></table><h2 id="tts-voices-optional" tabindex="-1">TTS Voices (Optional) <a class="header-anchor" href="#tts-voices-optional" aria-label="Permalink to &quot;TTS Voices (Optional)&quot;">​</a></h2><p>The app uses <a href="https://github.com/rhasspy/piper" target="_blank" rel="noreferrer">Piper TTS</a> which uses the CPU and is not very resource-intensive. Here are resources to find voices:</p><ul><li><a href="https://rhasspy.github.io/piper-samples/" target="_blank" rel="noreferrer">Piper TTS Voice Samples</a></li></ul><p>When importing a voice, you&#39;ll need to down load and select both a <code>.onnx</code> and <code>.json</code> file. The <code>.json</code> file&#39;s name should include the full name of the <code>.onnx</code> file (e.g. <code>en_US-lessac-medium.onnx</code> and <code>en_US-lessac-medium.onnx.json</code>).</p><h2 id="speech-to-text-models-optional" tabindex="-1">Speech-to-Text Models (Optional) <a class="header-anchor" href="#speech-to-text-models-optional" aria-label="Permalink to &quot;Speech-to-Text Models (Optional)&quot;">​</a></h2><p>I&#39;ve been using the Distill-Whisper large-v3 model for increased speeds and lower VRAM usage.</p><p>To download, go to the link below and click the &quot;Files and versions&quot; tab, then click on the file &quot;ggml-distil-large-v3.bin&quot; and finally click on Download.</p><table tabindex="0"><thead><tr><th>Model</th><th>File Size</th><th>Est. VRAM Usage</th></tr></thead><tbody><tr><td><a href="https://huggingface.co/distil-whisper/distil-large-v3-ggml" target="_blank" rel="noreferrer">Distill-Whisper large-v3</a></td><td>1.52GB</td><td>??GB</td></tr></tbody></table>',24)]))}const m=t(d,[["render",l]]);export{p as __pageData,m as default};
